import './App.css';
import Web3 from 'web3';
import {useState,useEffect} from "react";
import { infuraApiKey } from './settings'
import WAValidator from 'wallet-address-validator';
import erc20ABI from './erc20'
import HDWalletProvider from "@truffle/hdwallet-provider";
const RPC_URL_ETH_MAINNET = 'https://mainnet.infura.io/v3/' + infuraApiKey
const RPC_URL_ETH_ROPSTENNET = 'https://ropsten.infura.io/v3/' + infuraApiKey

const web3List = {
    "ropsten":new Web3(RPC_URL_ETH_ROPSTENNET),
    "mainnet":new Web3(RPC_URL_ETH_MAINNET)
};
const tokenAddressList = {
    "mainnet":"0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2",
    "ropsten":"0x767fdee588dab3af251180965a69c36e1916fc38"
}
function App() {
  const [network,setNetwork] = useState('ropsten');
  const [senderAddr,setSenderAddr] = useState('');
  const [senderSecret,setSenderSecret] = useState('');
  const [receiverAddr,setReceiverAddr] = useState('0x5504c7C3c61311Ea509392039FcEb104dA1795BC');
  /*const [senderBalance,setSenderBalance] = useState('');*/
  const [sendAmount,setSendAmount] = useState(0);
  const [sending,setSending] = useState(false);
  const [message,setMessage] = useState('');
  useEffect(()=>{
       console.log("senderAddr & network change")
  },[senderAddr,network])
  const sendEth = async ()=>{
    var valid = WAValidator.validate(senderAddr, 'ETH', network=='ropsten'?'testnet':'prod');
    if(!valid){
        alert("please input valid sender address");
        return;
    }
      var valid = WAValidator.validate(receiverAddr, 'ETH', network=='ropsten'?'testnet':'prod');
      if(!valid){
          alert("please input valid receiver address");
          return;
      }
    if(!senderSecret){
          alert("please input valid secret");
          return;
    }
    if(sendAmount <= 0 ){
        alert("please input valid send amount");
        return;
    }
    if(sending) {
        alert("Current Transaction Pending ... ")
        return;
    }
    setSending(true);
    const web3 = web3List[network];
    const account = web3.eth.accounts.privateKeyToAccount(senderSecret);
    setMessage("Sending Start")
    web3.eth.getBalance(senderAddr).then(async (wei) =>{
          const balance = web3.utils.fromWei(wei, 'ether')
          if(balance < sendAmount){
              setMessage("send amount bigger than current balance")
              setSending(false);
              return;
          }
        const amount = await web3.utils.toWei(sendAmount.toString(),'ether');
        const gasPrice = web3.eth.gasPrice;
        const gasPriceHex = web3.utils.toHex(gasPrice);
        const gasLimitHex = web3.utils.toHex(3000000);
        const tx = {
            from:senderAddr,
            to:receiverAddr,
            value: amount,
            gasPrice: gasPriceHex,
            gasLimit: gasLimitHex,
        };
        web3.eth.accounts.signTransaction(tx, senderSecret).then(signedTx=>{
            const sentTx = web3.eth.sendSignedTransaction(signedTx.raw || signedTx.rawTransaction);
            console.log('transaction sent')
            sentTx.on("receipt", async receipt => {
                // do something when receipt comes back
                console.log("receipt",receipt.gasUsed,receipt.transactionHash);
                const gasUsed = web3.utils.fromWei(receipt.gasUsed.toString());
                setMessage(`Successfully sent\n Used Gas: ${gasUsed}eth\n Transaction Hash: ${receipt.transactionHash}`)
                setSending(false);
            });
            sentTx.on("error", err => {
                setMessage(`Transfer error ${err.message}`)
                setSending(false);
                // do something on transaction error
            });
        }).catch(err=>{
            console.log(err)
            setMessage(`Transfer error ${err.message}`)
            setSending(false);
        })
      }).catch(err => {
          console.log(err)
          setMessage(`Error ${err.message}`)
          setSending(false);
      });

 }
  return (

    <div className="App">
        <div className="network-container">
              Select Network Type:
              <select value={network} onChange={(e)=>{setNetwork(e.target.value)}}>
                 <option value='ropsten'>ropsten</option>
                 <option value='mainnet'>mainnet</option>
              </select>
        </div>
        <div className="address-container" style={{float:'left',padding:20,textAlign:'left'}}>
            <div><label>Sender Address:</label> <input type="text" value={senderAddr} onChange={(e)=>{setSenderAddr(e.target.value)}}/></div>
            <div><label>SenderPrivateKey:</label> <input type="text" value={senderSecret} onChange={(e)=>{setSenderSecret(e.target.value)}}/> </div>
            <div><label>Receiver Address:</label> <input type="text" onChange={(e)=>{setReceiverAddr(e.target.value)}} value={receiverAddr}/></div>
            <div><label>Send Amount:</label> <input type="number" onChange={(e)=>{setSendAmount(e.target.value)}} value={sendAmount}/></div>
            <button value="Send" onClick={sendEth}>Send</button>
            <strong className="message">{message}</strong>
        </div>
    </div>
  );
}

export default App;
